/// The radii: sm a chip or a key, md a row, lg a button or an input, xl a
/// card, xxl a dialog or the composer, xxxl the largest sheet.
pub mod radius {
    use gpui::{Pixels, px};
    pub const SM: Pixels = px(4.);
    pub const MD: Pixels = px(6.);
    pub const LG: Pixels = px(8.);
    pub const XL: Pixels = px(10.);
    pub const XXL: Pixels = px(12.);
    pub const XXXL: Pixels = px(16.);
}

/// The type scale, six sizes and nothing between.
pub mod text {
    use gpui::{Pixels, px};
    pub const MICRO: Pixels = px(11.);
    pub const CAPTION: Pixels = px(12.);
    pub const UI: Pixels = px(13.);
    pub const BODY: Pixels = px(14.);
    pub const HEADING: Pixels = px(16.);
    pub const DISPLAY: Pixels = px(20.);
}

/// Spacing, a 4px grid.
pub mod space {
    use gpui::{Pixels, px};
    pub const HAIR: Pixels = px(4.);
    pub const TIGHT: Pixels = px(8.);
    pub const SNUG: Pixels = px(12.);
    pub const BASE: Pixels = px(16.);
    pub const LOOSE: Pixels = px(24.);
    pub const WIDE: Pixels = px(32.);
}

/// Layer is one drop of a shadow: its offset, blur and spread in pixels, and
/// which of the palette's two shadow colours it is, at what strength.
pub struct Layer {
    pub x: f32,
    pub y: f32,
    pub blur: f32,
    pub spread: f32,
    pub deep: bool,
    pub strength: f32,
}

/// Elevation: what a menu or popover casts, and what a dialog does. A panel
/// at rest casts nothing.
pub const POP: &[Layer] = &[
    Layer { x: 0., y: 8., blur: 24., spread: -6., deep: false, strength: 1.00 },
    Layer { x: 0., y: 1., blur: 2., spread: 0., deep: false, strength: 0.50 },
];
pub const MODAL: &[Layer] = &[
    Layer { x: 0., y: 24., blur: 60., spread: -16., deep: true, strength: 0.70 },
];
